{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fcfbf9;--muted:#6b6b6b;--accent:#7a9f59;--card:#ffffff;--glass:rgba(255,255,255,0.6);font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#f7f9f6);color:#243028}
    header{background:url('assets/img/pattern.svg') no-repeat center/1200px, linear-gradient(90deg,#f7fdf3, #eef5eb);padding:28px 20px;box-shadow:0 2px 8px rgba(20,30,20,0.06)}
    nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;justify-content:space-between}
    .brand{font-weight:700;color:#1f3524}
    .navlinks{display:flex;gap:14px}
    .navlinks a{color:var(--muted);text-decoration:none;font-size:14px}
    main{max-width:1100px;margin:28px auto;padding:20px}
    .intro{display:flex;gap:24px;align-items:center}
    .lead{flex:1}
    .lead h1{margin:0;font-size:28px;color:#172717}
    .lead p{color:var(--muted);margin-top:8px}
    .cta{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:22px}
    .card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 18px rgba(20,30,20,0.06);min-height:180px;display:flex;flex-direction:column}
    .tier{font-weight:700;color:#274226}
    .price{font-size:22px;margin-top:6px}
    .desc{color:var(--muted);margin-top:8px;flex:1}
    .actions{display:flex;gap:10px;align-items:center;margin-top:12px}
    .secondary{background:transparent;border:1px solid #e6e6e6;padding:8px 10px;border-radius:8px;color:var(--muted)}
    .addons{margin-top:26px;background:linear-gradient(180deg,#fff,#fbfff6);padding:14px;border-radius:12px;box-shadow:inset 0 1px rgba(255,255,255,0.6)}
    .addon-item{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px dashed #eef2ea}
    footer{max-width:1100px;margin:36px auto;padding:12px 20px;color:var(--muted);font-size:13px}
    .note{font-size:13px;color:var(--muted);margin-top:12px}
    @media (max-width:900px){.grid{grid-template-columns:1fr} .intro{flex-direction:column} nav{padding:0 6px}}
  </style>
</head>
<body>
  <header>
    <nav>
      <div class="brand">{{BUSINESS_NAME}}</div>
      <div class="navlinks">
        <a href="index.html">Welcome</a>
        <a href="about.html">Our Story</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Journeys</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Praise</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </div>
    </nav>
  </header>
  <main>
    <section class="intro">
      <div class="lead">
        <h1>Practical pricing for steady momentum</h1>
        <p>Tailored plans that show how weekly habits add up. Pick the structure that fits your pace and see optional add-ons you can layer as you go.</p>
        <div style="margin-top:12px">
          <a class="cta" href="book.html">Reserve a clarity call</a>
          <a class="secondary" href="contact.html" style="margin-left:8px">Ask a question</a>
        </div>
      </div>
      <div style="width:260px;background:rgba(122,159,89,0.06);padding:14px;border-radius:12px;text-align:center">
        <div style="font-size:12px;color:var(--muted)">Quick match</div>
        <div style="font-weight:700;font-size:20px;margin-top:6px;color:#274226">Find a plan</div>
        <div style="margin-top:8px;color:var(--muted);font-size:13px">If you're unsure, start with Momentum.</div>
      </div>
    </section>

    <section class="grid" aria-label="packages">
      <div class="card">
        <div class="tier">Starter Ritual</div>
        <div class="price">$69 / week</div>
        <div class="desc">A focused, 4-week guide to anchor one new habit into your daily rhythm. Includes 1 check-in and a habit tracker.</div>
        <div class="actions">
          <a class="cta" href="book.html">Start 4 weeks</a>
          <a class="secondary" href="#">See details</a>
        </div>
      </div>

      <div class="card">
        <div class="tier">Momentum Plan</div>
        <div class="price">$149 / month</div>
        <div class="desc">A concentrated 3-month path that layers routines: sleep cues, movement anchors, and focused micro-practices for resilient days.</div>
        <div class="actions">
          <a class="cta" href="book.html">Join Momentum</a>
          <a class="secondary" href="#">Compare</a>
        </div>
      </div>

      <div class="card">
        <div class="tier">Anchor Program</div>
        <div class="price">$480 / quarter</div>
        <div class="desc">A strategic 12-week framework: weekly coaching, personalized habit scaffolds, and review + tweak sessions to lock in gains.</div>
        <div class="actions">
          <a class="cta" href="book.html">Book a slot</a>
          <a class="secondary" href="#">Request syllabus</a>
        </div>
      </div>
    </section>

    <section class="addons">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div style="font-weight:700">Add-ons</div>
        <div style="color:var(--muted);font-size:13px">Customize as you grow</div>
      </div>
      <div style="margin-top:12px">
        <div class="addon-item"><div>One-off strategy audit</div><div style="color:#274226;">$95</div></div>
        <div class="addon-item"><div>Weekly habit check-ins (per extra session)</div><div style="color:#274226;">$28</div></div>
        <div class="addon-item"><div>Personalized weekly cue plan (PDF)</div><div style="color:#274226;">$45</div></div>
      </div>
    </section>

    <div class="note">Prices are framed to reflect coaching, planning, and habit tools — not medical care. Outcomes focus on routines, frameworks, and habit formation that support everyday wellbeing.</div>

  </main>

  <footer>
    <div>Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="margin-top:8px">Serving {{CITY}}, {{STATE}}. Primary CTA: <a href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
  </footer>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Praise — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffdf9;--muted:#5f6b5a;--accent:#7a9f59;--card:#ffffff;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto}
    body{margin:0;background:linear-gradient(180deg,#f9fbf8,#ffffff);color:#233022}
    header{padding:20px 24px;background:url('assets/img/pattern.svg') no-repeat center/900px}
    .wrap{max-width:1000px;margin:18px auto;padding:0 18px}
    h1{margin:0;font-size:26px}
    p.lead{color:var(--muted);margin-top:6px}
    .gallery{display:flex;gap:20px;margin-top:18px}
    .rotator{flex:1;background:var(--card);border-radius:12px;padding:18px;box-shadow:0 8px 24px rgba(20,30,20,0.06)}
    .badgecol{width:220px}
    .testimonial{min-height:120px}
    .quote{font-style:italic;color:#1f3426}
    .who{margin-top:10px;color:var(--muted);font-size:13px}
    .controls{display:flex;gap:8px;margin-top:12px}
    .dot{width:10px;height:10px;border-radius:50%;background:#e6e6e6}
    .dot.active{background:var(--accent)}
    .badges{display:flex;flex-direction:column;gap:12px;background:linear-gradient(180deg,#f6fff2,#ffffff);padding:12px;border-radius:12px}
    .badge{display:flex;align-items:center;gap:10px;padding:8px;border-radius:8px;background:#fff;border:1px solid #eef5ea;cursor:pointer}
    .badge svg{width:36px;height:36px;flex-shrink:0}
    .tooltip{position:relative}
    .tooltip .tip{position:absolute;left:calc(100% + 10px);top:50%;transform:translateY(-50%);background:#fff;border-radius:8px;padding:8px;border:1px solid #e9f0e6;min-width:160px;color:#2b3a2a;box-shadow:0 10px 24px rgba(20,30,20,0.06);display:none}
    .badge:hover .tip{display:block}
    .cred{font-size:13px;color:var(--muted)}
    footer{margin-top:22px;color:var(--muted);font-size:13px}
    @media (max-width:900px){.gallery{flex-direction:column}.badgecol{width:100%}}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav style="display:flex;justify-content:space-between;align-items:center">
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="display:flex;gap:12px">
          <a href="index.html" style="color:var(--muted);text-decoration:none">Welcome</a>
          <a href="services.html" style="color:var(--muted);text-decoration:none">Offerings</a>
          <a href="book.html" style="color:var(--muted);text-decoration:none">Reserve</a>
        </div>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <h1>Stories of steady shifts</h1>
    <p class="lead">Short portraits of what small, repeated actions started to produce for people who wanted less noise and more predictable days.</p>

    <section class="gallery">
      <div class="rotator">
        <div id="testimonial" class="testimonial">
          <div class="quote" id="quote">"I began with one tiny evening cue. Three weeks later I noticed mornings felt calmer — not perfect, but quieter in a good way."</div>
          <div class="who" id="who">— A. from {{CITY}}</div>
        </div>

        <div class="controls" role="tablist" aria-label="testimonial controls">
          <div id="dots"></div>
          <div style="margin-left:auto;color:var(--muted);font-size:13px">Auto-rotate on • Pause on hover</div>
        </div>
      </div>

      <aside class="badgecol">
        <div style="font-weight:700;margin-bottom:8px">Credibility & proof</div>
        <div class="badges" id="badges">
          <div class="badge tooltip" data-tip="3-year program designs, used by small teams">
            <svg viewBox="0 0 24 24" fill="#7a9f59" xmlns="http://www.w3.org/2000/svg"><path d="M12 2l2.39 4.85L19 8.18l-3.24 2.66L16.18 16 12 13.77 7.82 16l.42-5.16L5 8.18l4.61-1.33L12 2z"/></svg>
            <div>
              <div style="font-weight:700">Practice Design</div>
              <div class="tip">Designs shaped for routine adoption across weeks.</div>
            </div>
            <div class="tip">Templates for habit scaffolding and cadence.</div>
          </div>

          <div class="badge tooltip" data-tip="Surveyed participants report clearer daily structures">
            <svg viewBox="0 0 24 24" fill="#3a6b4b" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10"/></svg>
            <div>
              <div style="font-weight:700">Participant Feedback</div>
              <div class="cred">Regular check-ins inform tweaks.</div>
            </div>
            <div class="tip">Participants highlighted improved focus and habit clarity.</div>
          </div>

          <div class="badge tooltip" data-tip="Independent educator partnerships">
            <svg viewBox="0 0 24 24" fill="#2b4f38" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="4" width="18" height="14" rx="2"/></svg>
            <div>
              <div style="font-weight:700">Educator Partnerships</div>
              <div class="cred">Co-created frameworks with learning specialists.</div>
            </div>
            <div class="tip">Shared methods for daily habit building.</div>
          </div>
        </div>
      </aside>
    </section>

    <footer>
      <div>See more stories or book a conversation: <a href="book.html">Reserve a slot</a></div>
      <div style="margin-top:8px;color:var(--muted)">Contact: {{EMAIL}} • Call: {{PHONE}}</div>
    </footer>
  </main>

  <script>
    // Rotating testimonial + dots
    (function(){
      const items = [
        {q:'"I began with one tiny evening cue. Three weeks later I noticed mornings felt calmer, with fewer sharp starts."', who:'— A. from {{CITY}}'},
        {q:'"We mapped a weekly ritual that actually fit our household. The trick was small wins, repeated."', who:'— M. in {{STATE}}'},
        {q:'"Coaching focused on repeatable moves, not grand plans. That made it simpler to stay with it."', who:'— J. (remote)'}
      ];
      let idx=0; const quoteEl=document.getElementById('quote'), whoEl=document.getElementById('who');
      const dotsEl=document.getElementById('dots');
      function renderDots(){dotsEl.innerHTML='';items.forEach((_,i)=>{const d=document.createElement('div');d.className='dot'+(i===idx?' active':'');d.style.display='inline-block';d.style.margin='0 6px';d.dataset.index=i;d.addEventListener('click',()=>{idx=i;update();});dotsEl.appendChild(d)});
      }
      function update(){quoteEl.textContent=items[idx].q;whoEl.textContent=items[idx].who;renderDots();}
      renderDots();
      let auto=setInterval(()=>{idx=(idx+1)%items.length;update();},5000);
      const rot=document.querySelector('.rotator');rot.addEventListener('mouseenter',()=>clearInterval(auto));rot.addEventListener('mouseleave',()=>auto=setInterval(()=>{idx=(idx+1)%items.length;update();},5000));
      update();
    })();

    // Badges: simple tooltip toggles (tooltips also shown on hover via CSS)
    (function(){
      const badges=document.querySelectorAll('.badge');
      badges.forEach(b=>{
        b.addEventListener('click',()=>{alert(b.querySelector('div>div').textContent + ' — ' + (b.dataset.tip||'More info'));});
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8fff5;--muted:#6a6f64;--accent:#7a9f59;--card:#ffffff;font-family:Inter, system-ui, -apple-system}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#ffffff);color:#233022}
    header{padding:18px;background:url('assets/img/pattern.svg') no-repeat center/900px}
    .container{max-width:980px;margin:20px auto;padding:0 18px}
    h1{margin:0;font-size:26px}
    p.lead{color:var(--muted);margin-top:8px}
    .layout{display:grid;grid-template-columns:1fr 360px;gap:18px;margin-top:18px}
    .panel{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 10px 30px rgba(20,30,20,0.06)}
    .goals{display:flex;flex-direction:column;gap:8px}
    .goal input{margin-right:8px}
    .meter{height:120px;display:flex;align-items:center;justify-content:center}
    .pathmap{border-radius:10px;padding:12px;background:linear-gradient(180deg,#fff,#f7fff2)}
    .day{width:12px;height:12px;border-radius:50%;background:#e6ede1;margin:4px}
    .day.active{background:var(--accent)}
    .days{display:flex;flex-wrap:wrap;width:100%}
    .legend{display:flex;gap:8px;margin-top:8px;color:var(--muted);font-size:13px}
    .btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;text-decoration:none;display:inline-block}
    form{display:flex;flex-direction:column;gap:10px}
    input[type=text],input[type=email],select{padding:10px;border-radius:8px;border:1px solid #eef2ea}
    @media (max-width:900px){.layout{grid-template-columns:1fr} .meter{height:auto}}
  </style>
</head>
<body>
  <header>
    <div class="container">
      <nav style="display:flex;justify-content:space-between;align-items:center">
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="display:flex;gap:12px">
          <a href="index.html" style="color:var(--muted);text-decoration:none">Welcome</a>
          <a href="programs.html" style="color:var(--muted);text-decoration:none">Journeys</a>
          <a href="pricing.html" style="color:var(--muted);text-decoration:none">Investment</a>
        </div>
      </nav>
    </div>
  </header>

  <main class="container">
    <h1>Reserve your exploratory call</h1>
    <p class="lead">Choose what you want to shift. We'll show a 30-day path map that outlines a gentle, daily plan you can try before committing.</p>

    <div class="layout">
      <section class="panel">
        <h3 style="margin-top:0">Pick goals</h3>
        <div class="goals" id="goals">
          <label class="goal"><input type="checkbox" value="sleep">Calmer sleep routine</label>
          <label class="goal"><input type="checkbox" value="movement">Short daily movement</label>
          <label class="goal"><input type="checkbox" value="focus">Clearer focused work windows</label>
          <label class="goal"><input type="checkbox" value="stress">Micro-stress tools</label>
          <label class="goal"><input type="checkbox" value="eating">Simpler meal cues</label>
        </div>

        <div style="margin-top:12px">
          <h4 style="margin:0">Commitment meter</h4>
          <div class="meter" id="meter" aria-hidden="false">
            <svg id="ring" width="96" height="96" viewBox="0 0 36 36">
              <path stroke="#e6efe6" stroke-width="4" fill="none" d="M18 2a16 16 0 1 0 0 32 16 16 0 1 0 0-32"/>
              <path id="progressRing" stroke="#7a9f59" stroke-width="4" fill="none" stroke-linecap="round" d="M18 2a16 16 0 1 0 0 32 16 16 0 1 0 0-32" stroke-dasharray="0 100"/>
              <text id="progressText" x="18" y="20" font-size="6" text-anchor="middle" fill="#274226">0%</text>
            </svg>
          </div>
        </div>

        <div style="margin-top:12px">
          <h4 style="margin:0">30-day path map</h4>
          <div class="pathmap" id="pathmap">
            <div class="days" id="days"></div>
            <div class="legend"><div>● Active</div><div style="opacity:0.6">● Rest</div></div>
          </div>
        </div>

      </section>

      <aside class="panel">
        <h3 style="margin-top:0">Book a time</h3>
        <form id="bookForm">
          <label>Name <input type="text" name="name" placeholder="Your name" required></label>
          <label>Email <input type="email" name="email" placeholder="you@domain.com" required></label>
          <label>Preferred plan
            <select name="plan">
              <option>Starter Ritual (4 weeks)</option>
              <option>Momentum Plan (3 months)</option>
              <option>Anchor Program (12 weeks)</option>
            </select>
          </label>
          <label>Notes <input type="text" name="notes" placeholder="A little about what you need"></label>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button class="btn" type="submit">Reserve your slot</button>
            <a href="contact.html" class="btn" style="background:#fff;color:var(--accent);border:1px solid #e6efe6;text-decoration:none;padding:10px 12px;border-radius:10px">Ask first</a>
          </div>
        </form>
        <div style="color:var(--muted);font-size:13px;margin-top:12px">We'll send a short planning guide and a 30-day starter map ahead of the call.</div>
      </aside>
    </div>

    <div style="margin-top:16px;color:var(--muted);font-size:13px">By reserving you agree to short pre-work that helps shape the first two weeks. We focus on routines, frameworks, and habit support — not medical advice.</div>
  </main>

  <script>
    // Progress meter + 30-day path map
    (function(){
      const goalsEl=document.getElementById('goals');
      const inputs=goalsEl.querySelectorAll('input[type=checkbox]');
      const progressRing=document.getElementById('progressRing');
      const progressText=document.getElementById('progressText');
      const daysContainer=document.getElementById('days');

      function renderDays(activeCount){
        daysContainer.innerHTML='';
        for(let i=1;i<=30;i++){
          const d=document.createElement('div');d.className='day';
          // Simple rule: active days depend on chosen goals and a gentle cadence
          const intensity = Math.min(1, (activeCount/inputs.length) + (i%3===0?0.2:0));
          if(Math.random() < intensity) d.classList.add('active');
          daysContainer.appendChild(d);
        }
      }

      function updateMeter(){
        const checked=[...inputs].filter(i=>i.checked).length;
        const pct=Math.round((checked/inputs.length)*100);
        // Stroke dash uses circle circumference approx 100 for simplicity
        progressRing.setAttribute('stroke-dasharray', pct + ' 100');
        progressText.textContent = pct + '%';
        renderDays(checked);
      }

      inputs.forEach(i=>i.addEventListener('change',updateMeter));
      // seed: pick 1 default
      inputs[0].checked=true;updateMeter();

      // Form submit: gather chosen goals and produce a textual path summary then simulate booking
      document.getElementById('bookForm').addEventListener('submit',function(e){
        e.preventDefault();
        const data=new FormData(e.target);
        const chosen = [...inputs].filter(i=>i.checked).map(i=>i.value);
        const summary = 'Goals: '+(chosen.length?chosen.join(', '):'None')+'\nWe will send a condensed 30-day map to ' + data.get('email') + '.';
        alert('Reserved.\n\n'+summary);
        e.target.reset(); inputs.forEach(i=>i.checked=false);updateMeter();
      });
    })();
  </script>
</body>
</html>"} 
